arguments.content:
* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1a1a2e;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.calculator {
  width: 340px;
  background: #16213e;
  border-radius: 24px;
  padding: 24px;
  box-shadow: 0 20px 60px rgba(0,0,0,.5);
}

.display {
  background: #0f3460;
  border-radius: 16px;
  padding: 20px 24px;
  margin-bottom: 20px;
  min-height: 100px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: flex-end;
  overflow: hidden;
}

.expression {
  font-size: 16px;
  color: #8a8a9a;
  min-height: 22px;
  word-break: break-all;
}

.current {
  font-size: 40px;
  color: #e0e0e0;
  font-weight: 300;
  word-break: break-all;
}

.keys {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

button {
  border: none;
  border-radius: 50%;
  height: 64px;
  font-size: 22px;
  cursor: pointer;
  background: #1a1a3e;
  color: #e0e0e0;
  transition: background .15s, transform .1s;
}

button:active { transform: scale(.93); }

button:hover { background: #252550; }

.fn { background: #2a2a5a; color: #a0c4ff; }
.fn:hover { background: #35356a; }

.op { background: #e94560; color: #fff; }
.op:hover { background: #ff6b81; }

.zero { grid-column: span 2; border-radius: 32px; text-align: left; padding-left: 28px; }

const display = document.getElementById('display');
const expression = document.getElementById('expression');

let current = '0', prev = '', operator = '', resetNext = false;

function update() {
  display.textContent = current.length > 12 ? parseFloat(current).toPrecision(10) : current;
}

function inputNum(n) {
  if (resetNext) { current = '0'; resetNext = false; }
  if (n === '.' && current.includes('.')) return;
  current = current === '0' && n !== '.' ? n : current + n;
  update();
}

function compute(a, op, b) {
  a = parseFloat(a); b = parseFloat(b);
  switch (op) {
    case 'add': return a + b;
    case 'subtract': return a - b;
    case 'multiply': return a * b;
    case 'divide': return b === 0 ? 'Error' : a / b;
  }
}

const opSymbol = { add: '+', subtract: '−', multiply: '×', divide: '÷' };

function handleOp(action) {
  if (action === 'clear') {
    current = '0'; prev = ''; operator = ''; resetNext = false;
    expression.textContent = ''; update(); return;
  }
  if (action === 'toggle') {
    current = String(-parseFloat(current)); update(); return;
  }
  if (action === 'percent') {
    current = String(parseFloat(current) / 100); update(); return;
  }
  if (action === 'equals') {
    if (operator && prev) {
      const result = compute(prev, operator, current);
      expression.textContent = `${prev} ${opSymbol[operator]} ${current} =`;
      current = String(result);
      operator = ''; prev = ''; resetNext = true;
      update();
    }
    return;
  }
  // arithmetic operator
  if (operator && prev && !resetNext) {
    const result = compute(prev, operator, current);
    current = String(result);
    update();
  }
  prev = current;
  operator = action;
  expression.textContent = `${current} ${opSymbol[action]}`;
  resetNext = true;
}

document.querySelector('.keys').addEventListener('click', e => {
  const btn = e.target.closest('button');
  if (!btn) return;
  if (btn.dataset.num !== undefined) inputNum(btn.dataset.num);
  else if (btn.dataset.action) handleOp(btn.dataset.action);
});

document.addEventListener('keydown', e => {
  if (e.key >= '0' && e.key <= '9' || e.key === '.') inputNum(e.key);
  else if (e.key === '+') handleOp('add');
  else if (e.key === '-') handleOp('subtract');
  else if (e.key === '*') handleOp('multiply');
  else if (e.key === '/') { e.preventDefault(); handleOp('divide'); }
  else if (e.key === 'Enter' || e.key === '=') handleOp('equals');
  else if (e.key === 'Escape' || e.key === 'c') handleOp('clear');
  else if (e.key === '%') handleOp('percent');
  else if (e.key === 'Backspace') {
    current = current.length > 1 ? current.slice(0, -1) : '0'; update();
  }
});
